func newCommodity() unsafe.Pointer { return unsafe.Pointer(new(commodity.Commodity)) }

func newNCommodity(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]commodity.Commodity, n)))
}

func ptrCommodity(p unsafe.Pointer, c int32) any {
	r := (*commodity.Commodity)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.HazardousMaterialID))
	case 4:
		return (*string)(unsafe.Pointer(&r.Status))
	case 5:
		return &r.Name
	case 6:
		return &r.Description
	case 7:
		return (**int64)(unsafe.Pointer(&r.MinTemperature))
	case 8:
		return (**int64)(unsafe.Pointer(&r.MaxTemperature))
	case 9:
		return &r.WeightPerUnit
	case 10:
		return &r.LinearFeetPerUnit
	case 11:
		return &r.LengthPerUnit
	case 12:
		return &r.WidthPerUnit
	case 13:
		return &r.HeightPerUnit
	case 14:
		return &r.MaxQuantityPerShipment
	case 15:
		return (*string)(unsafe.Pointer(&r.FreightClass))
	case 16:
		return &r.LoadingInstructions
	case 17:
		return &r.Stackable
	case 18:
		return &r.Fragile
	case 19:
		return &r.SearchVector
	case 20:
		return &r.Rank
	case 21:
		return &r.Version
	case 22:
		return &r.CreatedAt
	case 23:
		return &r.UpdatedAt
	}
	return nil
}

func valueCommodity(p unsafe.Pointer, c int32) any {
	r := (*commodity.Commodity)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		if r.HazardousMaterialID == "" {
			return nil
		}
		return string(r.HazardousMaterialID)
	case 4:
		return string(r.Status)
	case 5:
		return r.Name
	case 6:
		return r.Description
	case 7:
		if r.MinTemperature == nil {
			return nil
		}
		return int64(*r.MinTemperature)
	case 8:
		if r.MaxTemperature == nil {
			return nil
		}
		return int64(*r.MaxTemperature)
	case 9:
		if r.WeightPerUnit == nil {
			return nil
		}
		return *r.WeightPerUnit
	case 10:
		if r.LinearFeetPerUnit == nil {
			return nil
		}
		return *r.LinearFeetPerUnit
	case 11:
		if r.LengthPerUnit == nil {
			return nil
		}
		return *r.LengthPerUnit
	case 12:
		if r.WidthPerUnit == nil {
			return nil
		}
		return *r.WidthPerUnit
	case 13:
		if r.HeightPerUnit == nil {
			return nil
		}
		return *r.HeightPerUnit
	case 14:
		if r.MaxQuantityPerShipment == nil {
			return nil
		}
		return *r.MaxQuantityPerShipment
	case 15:
		if r.FreightClass == "" {
			return nil
		}
		return string(r.FreightClass)
	case 16:
		if r.LoadingInstructions == "" {
			return nil
		}
		return r.LoadingInstructions
	case 17:
		return r.Stackable
	case 18:
		return r.Fragile
	case 19:
		return r.SearchVector
	case 20:
		return r.Rank
	case 21:
		return r.Version
	case 22:
		return r.CreatedAt
	case 23:
		return r.UpdatedAt
	}
	return nil
}

func attachCommodity(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*commodity.Commodity)(p)
	switch rel {
	case 0:
		r.HazardousMaterial = (*hazardousmaterial.HazardousMaterial)(child)
	}
}

func beforeCreateCommodity(ctx context.Context, p unsafe.Pointer) error {
	return (*commodity.Commodity)(p).BeforeCreate(ctx)
}

